CREATE TABLE dbo.Assets (
  AssetId UNIQUEIDENTIFIER NOT NULL CONSTRAINT DF_Assets_Id DEFAULT NEWSEQUENTIALID(), BranchId UNIQUEIDENTIFIER NOT NULL,
  AssetCode VARCHAR(40) NOT NULL, Name NVARCHAR(200) NOT NULL, AssetType VARCHAR(50) NOT NULL, Status VARCHAR(20) NOT NULL CONSTRAINT DF_Assets_Status DEFAULT 'ACTIVE',
  LastMaintenanceAt DATETIME2 NULL, NextMaintenanceDueAt DATETIME2 NULL, CalibrationExpiresAt DATETIME2 NULL, ResponsibleUserId UNIQUEIDENTIFIER NULL,
  CreatedAt DATETIME2 NOT NULL CONSTRAINT DF_Assets_CreatedAt DEFAULT SYSUTCDATETIME(), CreatedBy VARCHAR(100) NOT NULL, Version ROWVERSION NOT NULL,
  CONSTRAINT PK_Assets PRIMARY KEY(AssetId), CONSTRAINT UQ_Assets_Code UNIQUE(AssetCode), CONSTRAINT FK_Assets_Branch FOREIGN KEY(BranchId) REFERENCES dbo.Branches(BranchId),
  CONSTRAINT FK_Assets_Responsible FOREIGN KEY(ResponsibleUserId) REFERENCES dbo.Users(UserId), CONSTRAINT CK_Assets_Status CHECK(Status IN ('ACTIVE','MAINTENANCE','OUT_OF_SERVICE','RETIRED'))
);
CREATE TABLE dbo.SterilizationCycles (
  SterilizationCycleId UNIQUEIDENTIFIER NOT NULL CONSTRAINT DF_SterilizationCycles_Id DEFAULT NEWSEQUENTIALID(), AssetId UNIQUEIDENTIFIER NOT NULL,
  CycleNo VARCHAR(60) NOT NULL, StartedAt DATETIME2 NOT NULL, CompletedAt DATETIME2 NULL, IndicatorResult VARCHAR(20) NULL,
  Status VARCHAR(20) NOT NULL CONSTRAINT DF_SterilizationCycles_Status DEFAULT 'STARTED', CheckedBy UNIQUEIDENTIFIER NULL,
  CreatedAt DATETIME2 NOT NULL CONSTRAINT DF_SterilizationCycles_CreatedAt DEFAULT SYSUTCDATETIME(), CreatedBy VARCHAR(100) NOT NULL,
  CONSTRAINT PK_SterilizationCycles PRIMARY KEY(SterilizationCycleId), CONSTRAINT UQ_SterilizationCycles_No UNIQUE(CycleNo),
  CONSTRAINT FK_SterilizationCycles_Asset FOREIGN KEY(AssetId) REFERENCES dbo.Assets(AssetId), CONSTRAINT FK_SterilizationCycles_Checker FOREIGN KEY(CheckedBy) REFERENCES dbo.Users(UserId),
  CONSTRAINT CK_SterilizationCycles_Time CHECK(CompletedAt IS NULL OR CompletedAt > StartedAt), CONSTRAINT CK_SterilizationCycles_Result CHECK(IndicatorResult IS NULL OR IndicatorResult IN ('PASS','FAIL','INCONCLUSIVE')),
  CONSTRAINT CK_SterilizationCycles_Status CHECK(Status IN ('STARTED','COMPLETED','PASSED','FAILED','QUARANTINED','VOID'))
);
CREATE TABLE dbo.InstrumentPacks (
  InstrumentPackId UNIQUEIDENTIFIER NOT NULL CONSTRAINT DF_InstrumentPacks_Id DEFAULT NEWSEQUENTIALID(), PackCode VARCHAR(60) NOT NULL,
  SterilizationCycleId UNIQUEIDENTIFIER NOT NULL, PackType VARCHAR(50) NOT NULL, SterileFrom DATETIME2 NULL, ExpiresAt DATETIME2 NULL,
  Status VARCHAR(20) NOT NULL CONSTRAINT DF_InstrumentPacks_Status DEFAULT 'PENDING_RELEASE', ReleasedBy UNIQUEIDENTIFIER NULL,
  CreatedAt DATETIME2 NOT NULL CONSTRAINT DF_InstrumentPacks_CreatedAt DEFAULT SYSUTCDATETIME(), CreatedBy VARCHAR(100) NOT NULL, Version ROWVERSION NOT NULL,
  CONSTRAINT PK_InstrumentPacks PRIMARY KEY(InstrumentPackId), CONSTRAINT UQ_InstrumentPacks_Code UNIQUE(PackCode),
  CONSTRAINT FK_InstrumentPacks_Cycle FOREIGN KEY(SterilizationCycleId) REFERENCES dbo.SterilizationCycles(SterilizationCycleId), CONSTRAINT FK_InstrumentPacks_Releaser FOREIGN KEY(ReleasedBy) REFERENCES dbo.Users(UserId),
  CONSTRAINT CK_InstrumentPacks_Time CHECK(ExpiresAt IS NULL OR (SterileFrom IS NOT NULL AND ExpiresAt > SterileFrom)),
  CONSTRAINT CK_InstrumentPacks_Status CHECK(Status IN ('PENDING_RELEASE','RELEASED','USED','EXPIRED','DAMAGED','QUARANTINED'))
);
CREATE TABLE dbo.PackUsages (
  PackUsageId UNIQUEIDENTIFIER NOT NULL CONSTRAINT DF_PackUsages_Id DEFAULT NEWSEQUENTIALID(), InstrumentPackId UNIQUEIDENTIFIER NOT NULL,
  VisitId UNIQUEIDENTIFIER NOT NULL, PatientId UNIQUEIDENTIFIER NOT NULL, UsedAt DATETIME2 NOT NULL, UsedBy UNIQUEIDENTIFIER NOT NULL,
  CONSTRAINT PK_PackUsages PRIMARY KEY(PackUsageId), CONSTRAINT UQ_PackUsages_Pack UNIQUE(InstrumentPackId),
  CONSTRAINT FK_PackUsages_Pack FOREIGN KEY(InstrumentPackId) REFERENCES dbo.InstrumentPacks(InstrumentPackId), CONSTRAINT FK_PackUsages_Visit FOREIGN KEY(VisitId) REFERENCES dbo.Visits(VisitId),
  CONSTRAINT FK_PackUsages_Patient FOREIGN KEY(PatientId) REFERENCES dbo.Patients(PatientId), CONSTRAINT FK_PackUsages_User FOREIGN KEY(UsedBy) REFERENCES dbo.Users(UserId)
);
CREATE TABLE dbo.LabOrders (
  LabOrderId UNIQUEIDENTIFIER NOT NULL CONSTRAINT DF_LabOrders_Id DEFAULT NEWSEQUENTIALID(), VisitId UNIQUEIDENTIFIER NOT NULL,
  DoctorId UNIQUEIDENTIFIER NOT NULL, SupplierId UNIQUEIDENTIFIER NULL, Specimen NVARCHAR(300) NULL, Instructions NVARCHAR(1000) NOT NULL,
  DueAt DATETIME2 NOT NULL, Status VARCHAR(30) NOT NULL CONSTRAINT DF_LabOrders_Status DEFAULT 'ORDERED', QcResult VARCHAR(20) NULL,
  Cost DECIMAL(18,2) NOT NULL CONSTRAINT DF_LabOrders_Cost DEFAULT 0, CreatedAt DATETIME2 NOT NULL CONSTRAINT DF_LabOrders_CreatedAt DEFAULT SYSUTCDATETIME(), CreatedBy VARCHAR(100) NOT NULL, Version ROWVERSION NOT NULL,
  CONSTRAINT PK_LabOrders PRIMARY KEY(LabOrderId), CONSTRAINT FK_LabOrders_Visit FOREIGN KEY(VisitId) REFERENCES dbo.Visits(VisitId),
  CONSTRAINT FK_LabOrders_Doctor FOREIGN KEY(DoctorId) REFERENCES dbo.Users(UserId), CONSTRAINT FK_LabOrders_Supplier FOREIGN KEY(SupplierId) REFERENCES dbo.Suppliers(SupplierId),
  CONSTRAINT CK_LabOrders_Cost CHECK(Cost >= 0), CONSTRAINT CK_LabOrders_Qc CHECK(QcResult IS NULL OR QcResult IN ('PASS','FAIL','PENDING')),
  CONSTRAINT CK_LabOrders_Status CHECK(Status IN ('ORDERED','SENT','RECEIVED','QC_PENDING','ACCEPTED','REJECTED','CANCELLED'))
);
CREATE TABLE dbo.LabReworks (
  LabReworkId UNIQUEIDENTIFIER NOT NULL CONSTRAINT DF_LabReworks_Id DEFAULT NEWSEQUENTIALID(), LabOrderId UNIQUEIDENTIFIER NOT NULL,
  ReworkNo INT NOT NULL, Reason NVARCHAR(1000) NOT NULL, CostBearer VARCHAR(30) NOT NULL, Cost DECIMAL(18,2) NOT NULL,
  ApprovedBy UNIQUEIDENTIFIER NULL, Status VARCHAR(20) NOT NULL CONSTRAINT DF_LabReworks_Status DEFAULT 'REQUESTED',
  CreatedAt DATETIME2 NOT NULL CONSTRAINT DF_LabReworks_CreatedAt DEFAULT SYSUTCDATETIME(), CreatedBy VARCHAR(100) NOT NULL,
  CONSTRAINT PK_LabReworks PRIMARY KEY(LabReworkId), CONSTRAINT UQ_LabReworks_Order_No UNIQUE(LabOrderId, ReworkNo),
  CONSTRAINT FK_LabReworks_Order FOREIGN KEY(LabOrderId) REFERENCES dbo.LabOrders(LabOrderId), CONSTRAINT FK_LabReworks_Approver FOREIGN KEY(ApprovedBy) REFERENCES dbo.Users(UserId),
  CONSTRAINT CK_LabReworks_Cost CHECK(Cost >= 0), CONSTRAINT CK_LabReworks_Bearer CHECK(CostBearer IN ('CLINIC','LAB','PATIENT','PENDING_DECISION')),
  CONSTRAINT CK_LabReworks_Status CHECK(Status IN ('REQUESTED','APPROVED','IN_PROGRESS','COMPLETED','REJECTED'))
);
CREATE TABLE dbo.Warranties (
  WarrantyId UNIQUEIDENTIFIER NOT NULL CONSTRAINT DF_Warranties_Id DEFAULT NEWSEQUENTIALID(), ServiceLineId UNIQUEIDENTIFIER NOT NULL,
  PatientId UNIQUEIDENTIFIER NOT NULL, StartsAt DATE NOT NULL, ExpiresAt DATE NOT NULL, TermsJson NVARCHAR(MAX) NOT NULL,
  Status VARCHAR(20) NOT NULL CONSTRAINT DF_Warranties_Status DEFAULT 'ACTIVE', CreatedAt DATETIME2 NOT NULL CONSTRAINT DF_Warranties_CreatedAt DEFAULT SYSUTCDATETIME(), CreatedBy VARCHAR(100) NOT NULL,
  CONSTRAINT PK_Warranties PRIMARY KEY(WarrantyId), CONSTRAINT FK_Warranties_ServiceLine FOREIGN KEY(ServiceLineId) REFERENCES dbo.ServiceLines(ServiceLineId),
  CONSTRAINT FK_Warranties_Patient FOREIGN KEY(PatientId) REFERENCES dbo.Patients(PatientId), CONSTRAINT CK_Warranties_Dates CHECK(ExpiresAt >= StartsAt),
  CONSTRAINT CK_Warranties_Json CHECK(ISJSON(TermsJson)=1), CONSTRAINT CK_Warranties_Status CHECK(Status IN ('ACTIVE','CLAIMED','EXPIRED','VOID'))
);
CREATE TABLE dbo.Incidents (
  IncidentId UNIQUEIDENTIFIER NOT NULL CONSTRAINT DF_Incidents_Id DEFAULT NEWSEQUENTIALID(), IncidentType VARCHAR(50) NOT NULL,
  VisitId UNIQUEIDENTIFIER NULL, ObjectType VARCHAR(80) NULL, ObjectId UNIQUEIDENTIFIER NULL, Severity VARCHAR(20) NOT NULL,
  Description NVARCHAR(2000) NOT NULL, OwnerId UNIQUEIDENTIFIER NOT NULL, DueAt DATETIME2 NULL,
  Status VARCHAR(20) NOT NULL CONSTRAINT DF_Incidents_Status DEFAULT 'OPEN', Resolution NVARCHAR(2000) NULL,
  CreatedAt DATETIME2 NOT NULL CONSTRAINT DF_Incidents_CreatedAt DEFAULT SYSUTCDATETIME(), CreatedBy VARCHAR(100) NOT NULL, Version ROWVERSION NOT NULL,
  CONSTRAINT PK_Incidents PRIMARY KEY(IncidentId), CONSTRAINT FK_Incidents_Visit FOREIGN KEY(VisitId) REFERENCES dbo.Visits(VisitId),
  CONSTRAINT FK_Incidents_Owner FOREIGN KEY(OwnerId) REFERENCES dbo.Users(UserId), CONSTRAINT CK_Incidents_Severity CHECK(Severity IN ('LOW','MEDIUM','HIGH','CRITICAL')),
  CONSTRAINT CK_Incidents_Status CHECK(Status IN ('OPEN','IN_PROGRESS','RESOLVED','CLOSED'))
);
